1	package events
2	
3	import (
4		"errors"
5		"fmt"
6		"maps"
7		"sort"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// MaxBatchPayloadBytes bounds what one save may hold in the on-disk save
14	// format (MarshalBatch): 64 MiB in 1024*1024-byte units, matching the durable
15	// frame capacity. It measures the encoded JSON content of the newly saved
16	// events only — not any replayed events and not the surrounding frame
17	// header. A batch encoding to exactly this size is still accepted; only a
18	// larger encoding is rejected.
19	const MaxBatchPayloadBytes = 64 << 20
20	
21	// BeforeCommit persists a batch of brand-new events. It runs while the
22	// timeline lock is held and before the batch becomes visible to queries, so a
23	// successful return guarantees the batch is durable and committed atomically.
24	// Returning an error rejects the batch without touching the timeline.
25	type BeforeCommit func(persisted []Event) error
26	
27	// Timeline is a concurrency-safe, de-duplicated event timeline that accepts
28	// whole batches and reports replays of already-stored events.
29	type Timeline struct {
30		mu     sync.RWMutex
31		byID   map[string]Event
32		events []Event
33	}
34	
35	// NewTimeline returns an empty timeline.
36	func NewTimeline() *Timeline {
37		return &Timeline{byID: make(map[string]Event)}
38	}
39	
40	// IngestResult counts how a batch was applied: Created events are new,
41	// Replayed events matched an existing event with the same id and content.
42	type IngestResult struct {
43		Created  int
44		Replayed int
45	}
46	
47	// OversizeBatchError reports that the brand-new events of a batch encode to
48	// more than MaxBatchPayloadBytes in the save format. It is a property of the
49	// request content, not of the storage: nothing is written, the store stays
50	// usable without a restart, the rejected ids remain free, and the same
51	// events are accepted once submitted in smaller batches. Replayed events are
52	// not part of the measured payload.
53	type OversizeBatchError struct {
54		Size  int
55		Limit int
56	}
57	
58	func (e *OversizeBatchError) Error() string {
59		return fmt.Sprintf("event batch saves to %d bytes, exceeding the %d byte save capacity; reduce the amount of content in a single submission", e.Size, e.Limit)
60	}
61	
62	// IsOversizeBatchError reports whether err is a batch that exceeds the save
63	// capacity, as opposed to a validation, conflict, or storage failure.
64	func IsOversizeBatchError(err error) bool {
65		var target *OversizeBatchError
66		return errors.As(err, &target)
67	}
68	
69	// Ingest normalizes and validates every event first, then checks the whole
70	// batch against existing events and itself. Validation failures produce a
71	// ValidationError; duplicate ids with differing content, or a repeated id
72	// within the batch, produce a ConflictError. Nothing is stored when an error
73	// is returned.
74	//
75	// New events are passed to beforeCommit for durable storage; only after it
76	// succeeds does the batch become visible, so concurrent readers see either
77	// the complete batch or none of it.
78	func (t *Timeline) Ingest(batch []Event, beforeCommit BeforeCommit) (IngestResult, error) {
79		normalized := make([]Event, len(batch))
80		for i, event := range batch {
81			norm, err := Normalize(event)
82			if err != nil {
83				return IngestResult{}, err
84			}
85			normalized[i] = norm
86		}
87	
88		t.mu.Lock()
89		defer t.mu.Unlock()
90	
91		pending := make(map[string]struct{}, len(normalized))
92		var created []Event
93		var result IngestResult
94		for _, event := range normalized {
95			if _, repeated := pending[event.ID]; repeated {
96				return IngestResult{}, &ConflictError{Reason: "event id repeats within batch"}
97			}
98			pending[event.ID] = struct{}{}
99			if existing, ok := t.byID[event.ID]; ok {
100				if !sameEvent(existing, event) {
101					return IngestResult{}, &ConflictError{Reason: "event id already exists with different content"}
102				}
103				result.Replayed++
104				continue
105			}
106			created = append(created, event)
107			result.Created++
108		}
109	
110		// Only brand-new events are saved, so only they count toward the save
111		// capacity: a batch made entirely (or partly) of identical retries is
112		// measured by what would actually be written. The check runs after
113		// validation and conflict checks but before beforeCommit, so an oversize
114		// batch neither touches durable storage nor marks the store unavailable.
115		if len(created) > 0 {
116			payload, err := MarshalBatch(created)
117			if err != nil {
118				return IngestResult{}, err
119			}
120			if len(payload) > MaxBatchPayloadBytes {
121				return IngestResult{}, &OversizeBatchError{Size: len(payload), Limit: MaxBatchPayloadBytes}
122			}
123			if beforeCommit != nil {
124				if err := beforeCommit(created); err != nil {
125					return IngestResult{}, err
126				}
127			}
128			for _, event := range created {
129				t.byID[event.ID] = event
130				t.events = append(t.events, event)
131			}
132			sort.SliceStable(t.events, func(i, j int) bool {
133				return byTimeThenID(t.events[i], t.events[j])
134			})
135		}
136		return result, nil
137	}
138	
139	// Load inserts events recovered from durable storage during startup. Every
140	// event must already be normalized; a duplicate id with differing content is
141	// reported as a conflict so the caller can fail rather than mutate data.
142	func (t *Timeline) Load(event Event) error {
