9	func TestNormalizeLabelsAbsenceSpellings(t *testing.T) {
10		for name, labels := range map[string]map[string]string{
11			"nil":   nil,
12			"empty": {},
13		} {
14			got, err := NormalizeLabels(labels)
15			if err != nil {
16				t.Fatalf("%s: %v", name, err)
17			}
18			if got != nil {
19				t.Fatalf("%s: want nil, got %v", name, got)
20			}
21		}
22	}
23	
24	func TestNormalizeLabelsTrimsAndKeepsCase(t *testing.T) {
25		got, err := NormalizeLabels(map[string]string{"  Env ": " Prod ", "region": "cn-north 1"})
26		if err != nil {
27			t.Fatal(err)
28		}
29		if len(got) != 2 || got["Env"] != "Prod" || got["region"] != "cn-north 1" {
30			t.Fatalf("trimming/case wrong: %v", got)
31		}
32	}
33	
34	func TestNormalizeLabelsRejectsInvalid(t *testing.T) {
35		tooMany := make(map[string]string, MaxLabelsPerEvent+1)
36		for i := 0; i < MaxLabelsPerEvent+1; i++ {
37			tooMany[string(rune('a'+i))] = "v"
38		}
39		cases := map[string]map[string]string{
40			"empty name after trim":  {"   ": "v"},
41			"empty value after trim": {"env": "  "},
42			"name too long":          {strings.Repeat("n", MaxLabelNameRunes+1): "v"},
43			"value too long":         {"env": strings.Repeat("v", MaxLabelValueRunes+1)},
44			"too many labels":        tooMany,
45			"trim collision":         {"env": "prod", " env ": "prod"},
46			"trim collision differ":  {"env": "prod", "env\t": "stage"},
47		}
48		for name, labels := range cases {
49			t.Run(name, func(t *testing.T) {
50				if _, err := NormalizeLabels(labels); !IsValidationError(err) {
51					t.Fatalf("want ValidationError, got %v", err)
52				}
53			})
54		}
55	}
56	
57	func TestNormalizeLabelsAllowsLimitsAndUnicode(t *testing.T) {
58		exact := make(map[string]string, MaxLabelsPerEvent)
59		for i := 0; i < MaxLabelsPerEvent-2; i++ {
60			exact[string(rune('a'+i))] = "v"
61		}
62		exact["名字"] = strings.Repeat("值", MaxLabelValueRunes)
63		exact[strings.Repeat("名", MaxLabelNameRunes-1)+"x"] = "v"
64		got, err := NormalizeLabels(exact)
65		if err != nil {
66			t.Fatal(err)
67		}
68		if len(got) != MaxLabelsPerEvent {
69			t.Fatalf("unexpected count: %d", len(got))
70		}
71	}
72	
73	func TestParseLabelConditions(t *testing.T) {
74		got, err := ParseLabelConditions([]string{" env = prod ", "version=v2=rc1"})
75		if err != nil {
76			t.Fatal(err)
77		}
78		if len(got) != 2 || got["env"] != "prod" || got["version"] != "v2=rc1" {
79			t.Fatalf("conditions wrong: %v", got)
80		}
81		if none, err := ParseLabelConditions(nil); err != nil || none != nil {
82			t.Fatalf("no params must give nil, got %v, %v", none, err)
83		}
84	}
85	
86	func TestParseLabelConditionsRejectsInvalid(t *testing.T) {
87		tooMany := make([]string, MaxLabelFilters+1)
88		for i := range tooMany {
89			tooMany[i] = string(rune('a'+i)) + "=v"
90		}
91		cases := map[string][]string{
92			"too many":          tooMany,
93			"empty condition":   {""},
94			"no equals":         {"env"},
95			"empty name":        {"=prod"},
96			"blank name":        {"   =prod"},
97			"empty value":       {"env="},
98			"blank value":       {"env=  "},
99			"name too long":     {strings.Repeat("n", MaxLabelNameRunes+1) + "=v"},
100			"value too long":    {"env=" + strings.Repeat("v", MaxLabelValueRunes+1)},
101			"exact duplicate":   {"env=prod", "env=prod"},
102			"trimmed duplicate": {"env=prod", " env =stage"},
103		}
104		for name, raw := range cases {
105			t.Run(name, func(t *testing.T) {
106				if _, err := ParseLabelConditions(raw); !IsValidationError(err) {
107					t.Fatalf("want ValidationError, got %v", err)
108				}
109			})
110		}
111	}
112	
113	func ingestOne(t *testing.T, tl *Timeline, event Event) IngestResult {
114		t.Helper()
115		result, err := tl.Ingest([]Event{event}, nil)
116		if err != nil {
117			t.Fatalf("ingest: %v", err)
118		}
119		return result
120	}
121	
122	func TestIngestLabelReplayEquivalence(t *testing.T) {
123		tl := NewTimeline()
124		at := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
125		base := Event{ID: "e1", Service: "svc", Severity: "info", Message: "m", At: at,
126			Labels: map[string]string{"env": "prod", "version": "v2"}}
127		if got := ingestOne(t, tl, base); got.Created != 1 {
128			t.Fatalf("created: %+v", got)
129		}
130	
131		// Reordered keys with surrounding whitespace are the same labels.
132		retry := base
133		retry.Labels = map[string]string{" version ": " v2", "env": "prod "}
134		if got := ingestOne(t, tl, retry); got.Replayed != 1 || got.Created != 0 {
135			t.Fatalf("whitespace/order retry must replay: %+v", got)
136		}
137	
138		// Any added, removed, or changed label conflicts.
139		for name, labels := range map[string]map[string]string{
140			"added":   {"env": "prod", "version": "v2", "region": "cn1"},
141			"removed": {"env": "prod"},
142			"changed": {"env": "prod", "version": "v3"},
143			"case":    {"env": "Prod", "version": "v2"},
144		} {
145			t.Run(name, func(t *testing.T) {
146				changed := base
147				changed.Labels = labels
148				if _, err := tl.Ingest([]Event{changed}, nil); !IsConflictError(err) {
149					t.Fatalf("want ConflictError, got %v", err)
150				}
151			})
152		}
153	}
154	
155	func TestIngestNoLabelSpellingsEquivalent(t *testing.T) {
156		tl := NewTimeline()
157		at := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
158		plain := Event{ID: "e1", Service: "svc", Severity: "info", Message: "m", At: at}
159		if got := ingestOne(t, tl, plain); got.Created != 1 {
160			t.Fatalf("created: %+v", got)
161		}
162		withEmpty := plain
163		withEmpty.Labels = map[string]string{}
164		if got := ingestOne(t, tl, withEmpty); got.Replayed != 1 {
165			t.Fatalf("empty labels must replay a label-less event: %+v", got)
166		}
167		// And the reverse order: stored with empty set, retried without.
168		tl2 := NewTimeline()
169		if got := ingestOne(t, tl2, withEmpty); got.Created != 1 {
170			t.Fatalf("created: %+v", got)
171		}
172		if got := ingestOne(t, tl2, plain); got.Replayed != 1 {
173			t.Fatalf("missing labels must replay an empty-labels event: %+v", got)
174		}
175	}
176	
177	func TestQueryLabelFilters(t *testing.T) {
178		tl := NewTimeline()
179		at := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
180		events := []Event{
181			{ID: "e1", Service: "svc", Severity: "info", Message: "m", At: at, Labels: map[string]string{"env": "prod", "version": "v2"}},
182			{ID: "e2", Service: "svc", Severity: "info", Message: "m", At: at, Labels: map[string]string{"env": "prod"}},
183			{ID: "e3", Service: "svc", Severity: "info", Message: "m", At: at},
184		}
185		for _, event := range events {
186			ingestOne(t, tl, event)
187		}
188	
189		cases := []struct {
190			name  string
191			query Query
192			want  []string
193		}{
194			{"no filter", Query{}, []string{"e1", "e2", "e3"}},
195			{"single", Query{Labels: map[string]string{"env": "prod"}}, []string{"e1", "e2"}},
196			{"multiple AND", Query{Labels: map[string]string{"env": "prod", "version": "v2"}}, []string{"e1"}},
197			{"missing label", Query{Labels: map[string]string{"region": "cn1"}}, nil},
198			{"case sensitive", Query{Labels: map[string]string{"env": "Prod"}}, nil},
199			{"combined", Query{Service: "svc", Labels: map[string]string{"version": "v2"}}, []string{"e1"}},
200		}
201		for _, tc := range cases {
202			t.Run(tc.name, func(t *testing.T) {
203				got := tl.Query(tc.query)
204				if len(got) != len(tc.want) {
205					t.Fatalf("want %v, got %v", tc.want, got)
206				}
207				for i, event := range got {
208					if event.ID != tc.want[i] {
209						t.Fatalf("want %v, got %v", tc.want, got)
210					}
211				}
212			})
213		}
214	}
