216	func TestCompareLabelFilters(t *testing.T) {
217		tl := NewTimeline()
218		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
219		events := []Event{
220			{ID: "b1", Service: "svc", Severity: "info", Message: "m", At: base, Labels: map[string]string{"env": "prod"}},
221			{ID: "b2", Service: "svc", Severity: "info", Message: "m", At: base, Labels: map[string]string{"env": "stage"}},
222			{ID: "o1", Service: "svc", Severity: "info", Message: "m", At: base.Add(time.Hour), Labels: map[string]string{"env": "prod"}},
223			{ID: "o2", Service: "svc", Severity: "info", Message: "m", At: base.Add(time.Hour)},
